'use strict';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let data=[],world,likes=new Set(),positions={},light;
try{likes=new Set(JSON.parse(localStorage.getItem('blooming-environment-shortlist')||'[]'))}catch(e){}
function persist(){try{localStorage.setItem('blooming-environment-shortlist',JSON.stringify([...likes]))}catch(e){$('toast').textContent='Export your shortlist to keep it; browser storage is unavailable.'}}
function matches(p){let q=$('search').value.toLowerCase().trim(),t=$('town').value,c=$('category').value,l=$('licence').value;return(!q||[p.title,p.author,p.contents.join(' '),p.categories.join(' '),p.note].join(' ').toLowerCase().includes(q))&&(t==='all'||p.regions.includes(t))&&(c==='all'||p.categories.includes(c))&&(l==='all'||l==='general'&&p.licenseStatus==='Game use permitted'||l==='personal'&&p.licenseStatus==='Non-commercial only'||l==='review'&&/review/.test(p.licenseStatus)||l==='saved'&&likes.has(p.id))}
function guide(){let id=$('town').value,n=world.towns.find(t=>t.id===id),a=id==='roads'?world.roadArtGuide:n?.artGuide;if(!a){$('guide').innerHTML='<div class="eyebrow">One visual language, different places</div><h2>Choose a destination to see its style guide.</h2><p>Start with a coherent 16px village-and-nature base. Layer in approved specialty props: the flower gardens at Rosepetal, warm woodland at Sunveil, stone ruins near Thornrose and distinct river and coastal harbours.</p><p>These are candidates for review, not a plan to mix every pack into one scene.</p>';return}$('guide').innerHTML='<div class="eyebrow">Regional art direction · '+esc(n?n.name:'The long roads')+'</div><h2>'+esc(n?n.subtitle:'The spaces between towns')+'</h2><div class="palette">'+a.palette.map(c=>'<span class="swatch" style="background:'+c+'" title="'+c+'"></span>').join('')+'</div><p><strong>Buildings & materials:</strong> '+esc(a.architecture)+'</p><p><strong>Plant life:</strong> '+esc(a.nature)+'</p><p><strong>Current integration:</strong> '+esc(a.gaps)+'</p><p><strong>Start with:</strong> '+a.packs.map(id=>'<a href="#'+id+'">'+id+'</a>').join(' · ')+'</p><p><a href="world-map.html">Open the regional map ↗</a></p>'}
function render(){guide();let shown=data.filter(matches);$('count').textContent=shown.length+' / '+data.length+' sources · '+likes.size+' packs shortlisted';$('shortlist').style.display=likes.size?'block':'none';$('shortlist').innerHTML='<strong>Your review shortlist</strong><p>'+data.filter(p=>likes.has(p.id)).map(p=>esc(p.id+' · '+p.title)).join(' / ')+'</p>';$('grid').innerHTML=shown.map(p=>{let at=positions[p.id]||0,src=p.images[at];return '<article class="card" id="'+p.id+'"><div class="preview"><span class="number">'+p.id+' · ORIGINAL CREATOR PREVIEW</span>'+(src?'<button class="zoom" data-zoom="'+p.id+'" aria-label="Enlarge '+esc(p.title)+'"><img src="'+esc(src)+'" alt="'+esc(p.title)+' by '+esc(p.author)+'" loading="lazy"></button>':'<span>Preview on creator page</span>')+(p.images.length>1?'<button class="prev" data-cycle="'+p.id+'" data-delta="-1" aria-label="Previous preview">←</button><button class="next" data-cycle="'+p.id+'" data-delta="1" aria-label="Next preview">'+(at+1)+'/'+p.images.length+' →</button>':'')+'</div><div class="details"><div class="meta">'+esc(p.author)+' · '+esc(p.grid)+'</div><h2>'+esc(p.title)+'</h2><div class="badges">'+(p.inUse?'<span class="badge">Used in the game</span>':p.preferred?'<span class="badge">Start here</span>':'')+p.categories.map(c=>'<span class="badge">'+esc(c)+'</span>').join('')+'</div><div class="scope">'+esc(p.scope)+' · '+esc(p.licenseStatus)+'</div><p class="anim">'+p.contents.map(esc).join(' · ')+'</p>'+(p.note?'<p class="note">'+esc(p.note)+'</p>':'')+'<details><summary>Licence & credit notes</summary><p class="license">'+esc(p.license)+'</p></details><details><summary>Suggested locations</summary><p>'+p.regions.map(id=>esc(world.towns.find(t=>t.id===id)?.name||'Connecting roads')).join(' · ')+'</p></details><div class="links"><a class="source" href="'+esc(p.url)+'" target="_blank" rel="noopener noreferrer">Creator & free download ↗</a><button class="packlike '+(likes.has(p.id)?'active':'')+'" data-like="'+p.id+'" aria-label="Shortlist '+esc(p.title)+'" aria-pressed="'+likes.has(p.id)+'">'+(likes.has(p.id)?'★':'☆')+'</button></div></div></article>'}).join('')||'<div class="empty">No sources match. Try another filter.</div>';
$('grid').querySelectorAll('[data-like]').forEach(b=>b.onclick=()=>{likes.has(b.dataset.like)?likes.delete(b.dataset.like):likes.add(b.dataset.like);persist();render()});$('grid').querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{light=data.find(p=>p.id===b.dataset.zoom);showLight();$('lightbox').showModal()});$('grid').querySelectorAll('[data-cycle]').forEach(b=>b.onclick=()=>{const p=data.find(p=>p.id===b.dataset.cycle);positions[p.id]=((positions[p.id]||0)+Number(b.dataset.delta)+p.images.length)%p.images.length;const card=b.closest('.card');let image=card.querySelector('img');card.querySelector('.fallback')?.remove();image.style.display='';image.src=p.images[positions[p.id]];card.querySelector('.next').textContent=(positions[p.id]+1)+'/'+p.images.length+' →'});$('grid').querySelectorAll('img').forEach(img=>img.onerror=()=>{img.style.display='none';if(!img.parentElement.querySelector('.fallback')){let f=document.createElement('span');f.className='fallback';f.textContent='Preview unavailable — open creator page';img.parentElement.appendChild(f)}})}
function showLight(){let i=positions[light.id]||0;$('lightimg').src=light.images[i];$('lighttitle').textContent=light.id+' · '+light.title+' · '+(i+1)+' / '+light.images.length;$('lightnote').textContent=light.scope+' · '+light.note;$('lightsource').href=light.url}
$('close').onclick=()=>$('lightbox').close();for(let[id,d]of[['lightprev',-1],['lightnext',1]])$(id).onclick=()=>{positions[light.id]=((positions[light.id]||0)+d+light.images.length)%light.images.length;showLight()};$('search').oninput=render;for(let id of['town','category','licence'])$(id).onchange=render;$('clear').onclick=()=>{if(likes.size&&confirm('Clear this environment shortlist?')){likes.clear();persist();render()}};
$('export').onclick=()=>{if(!likes.size){$('toast').textContent='Star a pack first to add it to your shortlist.';return}let txt='BLOOMING QUEST — ENVIRONMENT REVIEW SHORTLIST\nReview preferences only; exporting does not change existing game placements.\n\n'+data.filter(p=>likes.has(p.id)).map(p=>p.id+' · '+p.title+' — '+p.author+'\n'+p.url+'\nFree scope: '+p.scope+'\nLicence: '+p.license+'\n').join('\n');let url=URL.createObjectURL(new Blob([txt],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='blooming-environment-shortlist.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
Promise.all([fetch('environment-catalog.json?v=18').then(r=>{if(!r.ok)throw Error('Source catalogue failed to load');return r.json()}),fetch('world.json?v=18').then(r=>{if(!r.ok)throw Error('World guide failed to load');return r.json()})]).then(([packs,w])=>{data=packs;world=w;$('packs').textContent=data.length;$('licsummary').textContent=data.filter(p=>p.licenseStatus==='Game use permitted').length+' sources state general game-use permission · '+data.filter(p=>p.licenseStatus==='Non-commercial only').length+' are non-commercial only · '+data.filter(p=>/review/.test(p.licenseStatus)).length+' need sample or licence-file review before use.';for(let n of world.towns.concat([{id:'roads',name:'Long connecting roads'}])){let o=document.createElement('option');o.value=n.id;o.textContent=n.name;$('town').appendChild(o);let b=document.createElement('button');b.textContent=n.name;b.onclick=()=>{$('town').value=n.id;render()};$('regionlinks').appendChild(b)}for(let c of [...new Set(data.flatMap(p=>p.categories))].sort()){let o=document.createElement('option');o.value=c;o.textContent=c;$('category').appendChild(o)}let requested=new URLSearchParams(location.search).get('town');if(world.towns.some(t=>t.id===requested)||requested==='roads')$('town').value=requested;render()}).catch(e=>$('count').textContent=e.message+' — refresh to retry.');
